// Simulamos un sensor de temperatura
msg.payload = {
    temp: 20 + Math.random() * 5, // Numero aleatorio entre 20 y 25
    humedad: 50
};
// La "measurement" es como el nombre de la tabla
msg.measurement = "cuarto_servidor";
return msg;

// Obtener el payload parseado
var rawData = msg.payload;
var device = rawData.device_id;
var outputPoints = [];

// Recorremos las claves dentro de "sensors" (mpu_1, mpu_2, etc.)
// Esto hace que el código funcione igual si hay 1, 2 o 20 sensores.
for (var sensorName in rawData.sensors) {
    if (rawData.sensors.hasOwnProperty(sensorName)) {
        var readings = rawData.sensors[sensorName];

        // Estructura para nodo node-red-contrib-influxdb
        outputPoints.push({
            measurement: "aceleracion_raw", // Nombre de la tabla
            tags: {
                host: device,          // Tag: qué ESP8266 es
                sensor_id: sensorName  // Tag: qué MPU es (mpu_1 o mpu_2)
            },
            fields: {
                ax: parseFloat(readings.ax),
                ay: parseFloat(readings.ay),
                az: parseFloat(readings.az)
            },
            // Opcional: Si el ESP envía timestamp, úsalo. Si no, Influx usa la hora actual.
            // timestamp: new Date() 
        });
    }
}

// --- 1. PREPARACIÓN DE DATOS ---
var inputData = msg.payload;

// Aseguramos que sea un objeto JSON
if (typeof inputData === "string") {
    try { inputData = JSON.parse(inputData); } catch (e) { return null; }
}

var nodeId = inputData.id || "unknown";

// --- 2. FILTRO DE SEGURIDAD ---
// (Mantenemos tu seguridad para evitar simuladores)
var validSensors = ["Dango_Node_001", "Dango_Node_002", "Telescopio_01", "Industria_SRO"];
if (!validSensors.includes(nodeId)) {
    // Si quieres ver un aviso en el debug, descomenta la siguiente línea:
    // node.warn("ID desconocido bloqueado: " + nodeId);
    return null; 
}

// --- 3. CONTEXTO Y TAGS ---
var clientName = "Dango_Prototype";
var locationName = "Lab_General";
var ssid = inputData.wifi || "Desconocida"; // Preparado para cuando el ESP lo envíe

if (nodeId === "Dango_Node_001" || nodeId === "Telescopio_01") {
    clientName = "Observatorio_Nacional";
    locationName = "Base_Acimutal";
} else if (nodeId === "Dango_Node_002") {
    clientName = "Industria_SRO";
    locationName = "Cinta_Transportadora";
}

// --- 4. CONSTRUCCIÓN PARA STACKHERO INFLUXDB ---
var dataPoints = [];

// Función auxiliar para crear el objeto de dato
function createPoint(sensorCode, d) {
    return {
        measurement: 'vibration_sensor',
        tags: {
            client: clientName,           // Tag Cliente
            location: locationName,       // Tag Lugar
            node: nodeId,                 // Tag ID del Nodo
            sensor: sensorCode,           // Tag Sensor (s1, s2)
            redSSID: ssid,                // Tag Red Wifi
            hw_ver: '1.5',                // Tag Versión Hardware
            sw_ver: '2.5.1'               // Tag Versión Software
        },
        fields: {
            ax: parseFloat(d.ax),
            ay: parseFloat(d.ay),
            az: parseFloat(d.az),
            // Calculamos magnitud aquí mismo
            mag_acc: parseFloat(Math.sqrt(d.ax*d.ax + d.ay*d.ay + d.az*d.az).toFixed(4))
        },
        timestamp: Date.now() // Usamos hora actual del servidor
    };
}

// Procesamos s1 y s2 si existen
if (inputData.s1) dataPoints.push(createPoint("s1", inputData.s1));
if (inputData.s2) dataPoints.push(createPoint("s2", inputData.s2));

// Si no hay datos validos, salir
if (dataPoints.length === 0) return null;

// --- 5. SALIDA FINAL ---
// Esta es la estructura exacta que pide el nodo Stackhero
msg.payload = {
    bucket: 'Vibranet_data', // Tu bucket real
    precision: 'ms',         // Milisegundos (coincide con Date.now())
    data: dataPoints         // El array con los objetos
};

return msg;

// SIMULADOR DE NODO INDUSTRIAL (Ej: Motor de Cinta)
// ID diferente para que el sistema lo reconozca como otro cliente
var fakeNodeId = "Dango_Node_Sim_02"; 

// Generamos vibración sintética
// Usamos Math.sin() para simular rotación y Math.random() para ruido/vibración
var time = new Date().getTime() / 1000; // Tiempo en segundos
var freq = 5; // Frecuencia de vibración simulada (5Hz)

function getVibration(amplitude, noiseLevel) {
    // Señal base (onda) + Ruido aleatorio
    return (Math.sin(time * freq) * amplitude) + ((Math.random() - 0.5) * noiseLevel);
}

// Creamos el payload idéntico al del ESP8266 real
var simulatedPayload = {
    id: fakeNodeId,
    s1: {
        // Sensor 1: Mucha vibración (simula un motor desbalanceado)
        ax: getVibration(0.8, 0.2).toFixed(2),
        ay: getVibration(0.5, 0.1).toFixed(2),
        az: (9.8 + getVibration(0.2, 0.1)).toFixed(2) // Gravedad + vibración vertical
    },
    s2: {
        // Sensor 2: Poca vibración (estructura estable)
        ax: getVibration(0.05, 0.01).toFixed(2),
        ay: getVibration(0.05, 0.01).toFixed(2),
        az: (9.8 + getVibration(0.02, 0.01)).toFixed(2)
    }
};

msg.payload = simulatedPayload; // Enviamos como Objeto JSON
// IMPORTANTE: El nodo MQTT out debe encargarse de hacer JSON.stringify 
// o puedes hacerlo aquí con msg.payload = JSON.stringify(simulatedPayload);

// Usamos el mismo tópico que el real
msg.topic = "dango/iot/sensors";

return msg;

