// Así evitas que entre basura o simulaciones por error.
var validSensors = ["Dango_Node_001", "Dango_Node_002", "Telescopio_01", "Industria_SRO"];

if (!validSensors.includes(nodeId)) {
    node.warn("¡Intruso bloqueado! ID desconocido intentó entrar: " + nodeId);
    return null; // Detiene el flujo aquí. No llega al HTTP Request.
}

// --- 4. LÓGICA DE NEGOCIO (Tags) ---
var clientName = "Dango_Prototype";
var locationName = "Lab_General";

if (nodeId === "Dango_Node_001" || nodeId === "Telescopio_01") {
    clientName = "Observatorio_Nacional";
    locationName = "Base_Acimutal";
} else if (nodeId === "Dango_Node_002" || nodeId === "Industria_SRO") {
    clientName = "Industria_SRO";
    locationName = "Cinta_Transportadora";
}

// --- 5. CONSTRUCCIÓN DEL LINE PROTOCOL ---
var lines = [];

function addLine(sensorName, d) {
    var ax = parseFloat(d.ax);
    var ay = parseFloat(d.ay);
    var az = parseFloat(d.az);
    var mag = Math.sqrt(ax*ax + ay*ay + az*az).toFixed(4);

    var line = `vibration_sensor,client=${clientName},node=${nodeId},location=${locationName},sensor=${sensorName} ax=${ax},ay=${ay},az=${az},mag_acc=${mag}`;
    lines.push(line);
}

// Solo procesa si existen los campos
if (inputData.s1) addLine("s1", inputData.s1);
if (inputData.s2) addLine("s2", inputData.s2);

// --- 6. SALIDA ---
if (lines.length === 0) return null;

msg.payload = lines.join("\n");
msg.headers = {
    "Authorization": "Token " + token,
    "Content-Type": "text/plain; charset=utf-8",
    "Accept": "application/json"
};
msg.url = "http://" + ip_influx + ":8086/api/v2/write?org=" + encodeURIComponent(org) + "&bucket=" + encodeURIComponent(bucket) + "&precision=s";

return msg;

